import assert from 'node:assert/strict';
import test from 'node:test';
import { IndexNowBoundary, ManualNaverSearchAdvisorAdapter, NotConfiguredGoogleSearchConsoleAdapter, auditArticleSEO, buildContentKPI, buildInternalLinkGraph, buildSearchOperatorPackage, createSearchTrackingRegistration, normalizeGoogleAnalytics, normalizeUrlInspection, redactSecret, registerPublishedArticle, summarizeArticlePerformance, validateSitemapCandidate } from '../src/search/measurement.js';
const now = '2026-10-02T09:00:00+09:00';
const page = 'https://motusnova.blogspot.com/2026/09/5-ai.html';
const record = (patch = {}) => ({ provider: 'GOOGLE_SEARCH_CONSOLE', propertyId: 'sc-domain:motusnova.blogspot.com', pageUrl: page, canonicalUrl: page, query: 'AI 에이전트', country: 'kor', device: 'MOBILE', searchAppearance: null, date: '2026-10-01', clicks: 2, impressions: 20, ctr: .1, averagePosition: 4.5, collectedAt: now, sourceType: 'API', verificationStatus: 'VERIFIED', ...patch });
const unknownSitemap = (type) => ({ url: `https://motusnova.blogspot.com/${type}.xml`, status: 'UNKNOWN', lastCheckedAt: now, httpStatus: null, entryCount: null, lastModified: null, submissionState: 'UNKNOWN', provenance: 'not checked' });
test('Sprint 4H normalizes Google Search Analytics dimensions and metrics', () => { const rows = normalizeGoogleAnalytics({ propertyId: 'property', dimensions: ['date', 'page', 'query', 'country', 'device'], rows: [{ keys: ['2026-10-01', `${page}?b=2&a=1`, 'motus', 'kor', 'MOBILE'], clicks: 3, impressions: 30, ctr: .1, position: 5 }], collectedAt: now }); assert.equal(rows[0]?.canonicalUrl, `${page}?a=1&b=2`); assert.equal(rows[0]?.averagePosition, 5); });
test('Sprint 4H URL inspection normalization is null-safe', () => { assert.equal(normalizeUrlInspection(null, page, now), null); const item = normalizeUrlInspection({ indexStatusResult: { verdict: 'PASS', coverageState: 'Submitted and indexed' }, mobileUsabilityResult: {} }, page, now); assert.equal(item.indexStatus, 'PASS'); assert.equal(item.lastCrawlTime, null); assert.equal(item.mobileUsability, null); });
test('Sprint 4H returns NOT_CONFIGURED without credentials and no fake rows', async () => { const adapter = new NotConfiguredGoogleSearchConsoleAdapter(); assert.equal(adapter.connectionState, 'NOT_CONFIGURED'); assert.deepEqual(await adapter.listSitemaps('property'), []); assert.equal(await adapter.inspectUrl(page, 'property'), null); await assert.rejects(() => adapter.getSearchAnalytics({ propertyId: 'p', dimensions: ['date'], startDate: '2026-09-01', endDate: '2026-10-01' }), /NOT_CONFIGURED/); });
test('Sprint 4H validates non-empty same-domain sitemap XML', async () => { const fetcher = async () => new Response('<?xml version="1.0"?><urlset><url><loc>https://motusnova.blogspot.com/a</loc></url></urlset>', { status: 200, headers: { 'last-modified': 'Thu, 01 Oct 2026 00:00:00 GMT' } }); const result = await validateSitemapCandidate('https://motusnova.blogspot.com/sitemap.xml', 'https://motusnova.blogspot.com/', now, fetcher); assert.equal(result.status, 'AVAILABLE'); assert.equal(result.entryCount, 1); assert.equal(result.submissionState, 'UNKNOWN'); });
test('Sprint 4H rejects cross-domain, empty and invalid sitemap candidates', async () => { const never = async () => { throw new Error('must not fetch'); }; assert.equal((await validateSitemapCandidate('https://evil.invalid/sitemap.xml', 'https://motusnova.blogspot.com/', now, never)).status, 'INVALID'); const invalid = await validateSitemapCandidate('https://motusnova.blogspot.com/sitemap.xml', 'https://motusnova.blogspot.com/', now, async () => new Response('<urlset></urlset>', { status: 200 })); assert.equal(invalid.status, 'INVALID'); assert.equal(invalid.entryCount, 0); });
test('Sprint 4H keeps Naver unsupported checks manual-required or unknown', async () => { const status = await new ManualNaverSearchAdvisorAdapter().getStatus('https://motusnova.blogspot.com/'); assert.equal(status.siteRegistration, 'MANUAL_REQUIRED'); assert.equal(status.collectionState, 'MANUAL_REQUIRED'); assert.equal(status.sitemapSubmission, 'UNKNOWN'); });
test('Sprint 4H keeps IndexNow disabled by default', async () => { const boundary = new IndexNowBoundary(); await assert.rejects(() => boundary.notifyUpdatedUrl(), /DISABLED/); assert.equal(boundary.calls, 0); });
test('Sprint 4H has no Google Indexing API action for normal articles', () => { const google = new NotConfiguredGoogleSearchConsoleAdapter(); assert.equal('notifyUpdatedUrl' in google, false); assert.equal('indexUrl' in google, false); });
test('Sprint 4H SEO audit reports rules without arbitrary score', () => { const html = '<!doctype html><html><head><meta name="viewport" content="width=device-width"></head><body><article style="width:100%;max-width:100%"><h2>시장</h2><a href="https://openai.com/news">출처</a><img src="x" alt="차트"></article></body></html>'; const result = auditArticleSEO({ publicationId: 'p1', url: page, title: '국채금리와 AI 산업을 함께 읽는 오늘의 시장 분석', metaDescription: '검증 자료를 바탕으로 시장을 정리합니다.', canonicalUrl: page, html }); assert.equal(result.singleH1, true); assert.equal(result.mobileSafe, true); assert.equal(result.externalSourceLinks, 1); assert.equal('score' in result, false); });
test('Sprint 4H internal link graph accepts explicit reasons and dedupes edges', () => { const graph = buildInternalLinkGraph([{ fromPublicationId: 'daily', toPublicationId: 'weekly', reason: 'DAILY_TO_WEEKLY' }, { fromPublicationId: 'daily', toPublicationId: 'weekly', reason: 'DAILY_TO_WEEKLY' }]); assert.deepEqual(graph, [{ fromPublicationId: 'daily', toPublicationId: 'weekly', reason: 'DAILY_TO_WEEKLY' }]); assert.throws(() => buildInternalLinkGraph([{ fromPublicationId: 'daily', toPublicationId: 'daily', reason: 'RELATED_TOPIC' }])); });
test('Sprint 4H aggregates article performance only inside requested period', () => { const summary = summarizeArticlePerformance({ publicationId: 'p1', category: 'AI', title: 'title', publishedAt: '2026-09-01T00:00:00Z', period: '7d', asOf: '2026-10-02', records: [record(), record({ date: '2026-09-01', clicks: 99, impressions: 99 })], sourceCount: 4, contentLength: 1000, reportType: 'DAILY' }); assert.equal(summary.google?.clicks, 2); assert.equal(summary.google?.impressions, 20); assert.equal(summary.naver.availableMetrics, null); });
test('Sprint 4H builds provider-safe category KPI', () => { const visibility = [{ ...registerPublishedArticle('p1', page), google: { ...registerPublishedArticle('p1', page).google, indexed: true } }]; const kpi = buildContentKPI([{ publicationId: 'p1', publicPostUrl: page, category: 'AI', publishedAt: '2026-10-01T00:00:00Z' }], visibility, [record()], '2026-10-02'); assert.equal(kpi.indexCoverageRate, 1); assert.equal(kpi.categoryPerformance.AI?.clicks, 2); assert.equal(kpi.google.searchImpressions, 20); assert.equal(kpi.naver.availableMetrics, null); });
test('Sprint 4H distinguishes measured zero from unknown metrics', () => { const publication = [{ publicationId: 'p1', publicPostUrl: page, category: 'AI', publishedAt: '2026-10-01T00:00:00Z' }]; const unknown = buildContentKPI(publication, [], [], '2026-10-02'); const zero = buildContentKPI(publication, [], [record({ clicks: 0, impressions: 0, ctr: 0, averagePosition: 0 })], '2026-10-02'); assert.equal(unknown.google.searchClicks, null); assert.equal(zero.google.searchClicks, 0); assert.equal(unknown.indexedArticles, null); });
test('Sprint 4H creates unknown search registration after publish', () => { const state = registerPublishedArticle('p1', page); assert.equal(state.google.indexed, null); assert.equal(state.naver.discovered, null); assert.equal(state.sitemapIncluded, null); });
test('Sprint 4H queues tracking after publish without claiming discovery or indexing', () => { const registration = createSearchTrackingRegistration('p1', page, now); assert.equal(registration.trigger, 'PUBLICATION_PUBLISHED'); assert.equal(registration.googleInspectionState, 'QUEUED'); assert.equal(registration.naverDiscoveryState, 'PENDING'); assert.equal(registration.visibility.google.indexed, null); });
test('Sprint 4H redacts secrets and exposes only an eight-character fingerprint', () => { const result = redactSecret('not-a-real-secret-value'); assert.equal(result.present, true); assert.match(result.fingerprint, /^[a-f0-9]{8}$/); assert.doesNotMatch(JSON.stringify(result), /not-a-real-secret-value/); });
test('Sprint 4H operator uses unknown instead of fake metrics and performs no remote actions', () => { const visibility = [registerPublishedArticle('p1', page)]; const seo = [auditArticleSEO({ publicationId: 'p1', url: page, title: '충분히 긴 검색용 금융시장 분석 제목입니다', metaDescription: '시장 분석 설명', canonicalUrl: page, html: '<meta name="viewport"><article style="max-width:100%"><h2>시장</h2></article>' })]; const output = buildSearchOperatorPackage({ generatedAt: now, googleState: 'NOT_CONFIGURED', naverState: 'MANUAL_REQUIRED', sitemap: unknownSitemap('sitemap'), rss: unknownSitemap('rss'), publications: [{ publicationId: 'p1' }], visibility, records: [], seo }); assert.equal(output.performance.clicks, null); assert.equal(output.articles.indexUnknown, 1); assert.deepEqual(output.remoteCalls, { blogger: 0, indexNow: 0, googleIndexingApi: 0 }); assert.deepEqual(output.commerce, { enabled: false }); });
